SELECT CASE WHEN event_type IN ('click', 'page_view') THEN 'tier_1' ELSE 'other' END AS event_type_group, event_type, SUM(CASE WHEN event_type = 'click' THEN duration_sec ELSE 0 END) AS click_duration_sec, MIN(event_time) AS min_event_time FROM web_events WHERE event_type IN ('search', 'purchase', 'add_to_cart') AND event_type IN ('click', 'page_view', 'purchase') GROUP BY CUBE(CASE WHEN event_type IN ('click', 'page_view') THEN 'tier_1' ELSE 'other' END, event_type) ORDER BY event_type;
